using static Bootcamp.Check;

IReadOnlyList<string> ModifiedProperties(IReadOnlyDictionary<string, object?> original, IReadOnlyDictionary<string, object?> current, string keyProperty)
{
    var changed = new List<string>();
    foreach (var (name, before) in original)
    {
        if (Equals(before, current[name])) continue;
        if (name == keyProperty) throw new InvalidOperationException($"The property '{name}' is part of a key and cannot be modified.");
        changed.Add(name);
    }
    return changed;
}

