// ──────────────────────────── types ──────────────────────────────────────

/// <summary>a stored Customers row (Id is the dictionary key)</summary>
record Row(string Name, string? Email);

class Db
{
    public Dictionary<int, Row> Rows { get; } = new();
    /// <summary>one line per UPDATE statement: "UPDATE Customers SET Name, Email WHERE Id = 1"</summary>
    public List<string> Updates { get; } = new();
}

class Customer
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string? Email { get; set; }
}

class Tracker(Db db)
{
    // Snapshot null = Update() marked every column modified
    private readonly Dictionary<int, (Customer Entity, Row? Snapshot)> _tracked = new();

    public Customer Load(int id)
    {
        var row = db.Rows[id];
        var entity = new Customer { Id = id, Name = row.Name, Email = row.Email };
        _tracked[id] = (entity, row);
        return entity;
    }

    public void Update(Customer entity)
    {
        if (_tracked.TryGetValue(entity.Id, out var t) && !ReferenceEquals(t.Entity, entity))
            throw new InvalidOperationException($"The instance of entity type 'Customer' cannot be tracked because another instance with the key value '{{Id: {entity.Id}}}' is already being tracked.");
        _tracked[entity.Id] = (entity, null);
    }

    public int SaveChanges()
    {
        var written = 0;
        foreach (var id in _tracked.Keys.ToList())
        {
            var (entity, snapshot) = _tracked[id];
            var columns = new List<string>();
            if (snapshot is null || snapshot.Name != entity.Name) columns.Add("Name");
            if (snapshot is null || snapshot.Email != entity.Email) columns.Add("Email");
            if (columns.Count == 0) continue;
            var stored = db.Rows[id];
            db.Rows[id] = new Row(columns.Contains("Name") ? entity.Name : stored.Name, columns.Contains("Email") ? entity.Email : stored.Email);
            db.Updates.Add($"UPDATE Customers SET {string.Join(", ", columns)} WHERE Id = {id}");
            _tracked[id] = (entity, new Row(entity.Name, entity.Email));
            written++;
        }
        return written;
    }
}

fund-csharp/19-ef-core-basics/02-tracked.explanation:
Keep, per tracked id, the entity and either its snapshot or a mark that every column is modified (here a null snapshot):

```csharp
public void Update(Customer entity)
{
    if (_tracked.TryGetValue(entity.Id, out var t) && !ReferenceEquals(t.Entity, entity))
        throw new InvalidOperationException("... is already being tracked.");
    _tracked[entity.Id] = (entity, null);          // every column modified
}
// SaveChanges: a column is written when the snapshot is null or differs; afterwards the snapshot = current values
```

The trap test catches the plausible wrong version that makes `Update` "helpful" by skipping null properties or comparing against the stored row: EF Core does neither, which is exactly why a partial request body bound to an entity and passed to `Update` nulls the columns it left out. A version that forgets to refresh the snapshot fails the second-save test by writing the same UPDATE twice. In real code, load the entity and copy the allowed DTO fields onto it.

