    var c = ctx.Find(1)!;
    c.Name = "Ana Lima";                                       // not saved yet
    db.Rows[1] = new Row("Ana (changed elsewhere)", "ana@other.example");
    var again = ctx.Query(1)!;
    Eq((again.Name, again.Email), ("Ana Lima", "ana@example.com"));
