/// <summary>a stored Customers row (Id is the dictionary key)</summary>
record Row(string Name, string? Email);

class Db
{
    public Dictionary<int, Row> Rows { get; } = new();
    /// <summary>round-trips to the database so far</summary>
    public int Queries { get; private set; }

    /// <summary>one SELECT by primary key (counts as a query even when nothing is found)</summary>
    public Row? Select(int id)
    {
        Queries++;
        return Rows.GetValueOrDefault(id);
    }
}

class Customer
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string? Email { get; set; }
}

class Context(Db db)
{
    private readonly Dictionary<int, Customer> _identityMap = new();

    public Customer? Find(int id) => _identityMap.TryGetValue(id, out var tracked) ? tracked : Query(id);

    public Customer? Query(int id)
    {
        var row = db.Select(id);
        if (row is null) return null;
        if (_identityMap.TryGetValue(id, out var tracked)) return tracked;   // identity resolution: keep local edits
        var entity = Materialise(id, row);
        _identityMap[id] = entity;
        return entity;
    }

    public Customer? QueryNoTracking(int id) => db.Select(id) is { } row ? Materialise(id, row) : null;

    private static Customer Materialise(int id, Row row) => new() { Id = id, Name = row.Name, Email = row.Email };
}

